SELECT id, create_user_name AS createUserName, create_time AS createTime, name, type_id AS typeId , charge_id AS chargeId, contacts, contact_tel_number AS contactTelNumber, disabled, address, org_id AS orgId, kingdee_warehouse_code AS kingdeeWarehouseCode, is_virtual AS isVirtual, approve_status AS approveStatus, is_enable_location as isEnableLocation FROM warehouse WHERE is_deleted=false
AND create_user_id IN
#{createUserId}
AND is_virtual = #{params.isVirtual}
AND is_enable_location = #{params.isEnableLocation}
AND address LIKE concat('%', #{params.address} ,'%')
AND name LIKE concat('%', #{params.name} ,'%')
AND contacts LIKE concat('%', #{params.contacts} ,'%')
AND type_id IN
#{typeId}
AND approve_status IN
#{approveStatus}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
create_time desc

