SELECT id AS warehouseId, name, type_id AS typeId , disabled, org_id AS orgId, kingdee_warehouse_code AS code FROM warehouse WHERE is_deleted=false
AND name ILIKE concat('%', #{params.name} ,'%')
AND kingdee_warehouse_code ILIKE concat('%', #{params.code} ,'%')
